import { AbstractSystem } from '../core/AbstractSystem.ts';
import { MarkerData, GeoJSONData } from '../data/index.ts';
import { Tiler } from '@rapid-sdk/math';
import { uiIcon } from '../ui/icon.ts';
import { utilQsString } from '@rapid-sdk/util';
import { utilSetTransform } from '../util/index.ts';
import { zoom, zoomIdentity } from 'd3-zoom';

import type { Context } from '../Context.ts';
import type { D3EnterSelection, D3Selection } from 'd3-selection';
import type { GeoJSONProps } from '../data/GeoJSONData.ts';
import type { MarkerProps } from '../data/MarkerData.ts';
import type { Tile, Vec2 } from '@rapid-sdk/math';
import type { ZoomBehavior } from 'd3-zoom';


/** Base URL for the Kartaview API (v1.0 endpoints) */
const KARTAVIEW_API = 'https://kartaview.org';
/** Base URL for the legacy OpenStreetCam API (v2.0 endpoints) */
const OPENSTREETCAM_API = 'https://api.openstreetcam.org';
/** Maximum number of images returned per API page request */
const MAXRESULTS = 1000;
/** Tile zoom level used for spatial partitioning of requests */
const TILEZOOM = 14;


/** Properties passed to `_cacheImage` to create or update an image */
interface ImageSource {
  /** Unique image identifier */
  id: PhotoID;
  /** ID of the sequence this image belongs to */
  sequenceID: SequenceID;
  /** Geographic location as [lon, lat] */
  loc: Vec2;
  /** Compass angle (heading) in degrees */
  ca: number;
  /** Whether this is a 360-degree panoramic image */
  isPano: boolean;
  /** Username of the photographer */
  captured_by?: string;
  /** Date/time when the image was captured */
  captured_at?: string;
  /** Position of this image within its sequence */
  sequenceIndex: number;
  /** Thumbnail image URL */
  imageLowUrl?: string;
  /** Medium-resolution image URL */
  imageMedUrl?: string;
  /** Full-resolution image URL */
  imageHighUrl?: string;
}


/** Properties for Kartaview photo markers */
export interface KartaviewImageProps extends MarkerProps {
  /** ID of the sequence this image belongs to */
  sequenceID: SequenceID;
  /** Index of this image within the sequence (may be sparse) */
  sequenceIndex: number;
  /** Compass angle (heading) in degrees */
  ca: number;
  /** Whether this is a panoramic image */
  isPano: boolean;
  /** When the image was captured */
  captured_at?: string;
  /** Who captured the image */
  captured_by?: string;
  /** Thumbnail URL */
  imageLowUrl?: string;
  /** Medium-size image URL */
  imageMedUrl?: string;
  /** High-resolution image URL */
  imageHighUrl?: string;
}

/** Properties for Kartaview sequence GeoJSONData data */
export interface KartaviewSequenceProps extends GeoJSONProps {
  /** Ordered (possibly sparse) array of image IDs in this sequence */
  imageIDs: PhotoID[];
  /** Rotation applied in the viewer (degrees) */
  rotation: number;
  /** Index of the first (earliest) image in the sequence */
  firstIndex: number;
  /** Whether this sequence contains panoramic images */
  isPano?: boolean;
  /** Capture date, copied from the earliest image */
  captured_at?: string;
  /** Capture author, copied from the earliest image */
  captured_by?: string;
}

/** A Kartaview image MarkerData with typed props */
export type KartaviewImage = MarkerData<KartaviewImageProps>;

/** A Kartaview sequence GeoJSONData with typed props */
export type KartaviewSequence = GeoJSONData<KartaviewSequenceProps>;


/**
 * `KartaviewService` loads photos and sequences from the Kartaview/OpenStreetCam APIs.
 * ('Kartaview' used to be named 'OpenStreetCam', and this code uses a mix of APIs to work.)
 * @see https://doc.kartaview.org/
 * @see https://api.openstreetcam.org/api/doc.html
 *
 * It also manages a simple embedded photo viewer,
 * allowing the user to zoom, pan, and rotate the photos.
 *
 * Events available:
 * - `imageChanged`
 */
export class KartaviewService extends AbstractSystem {

  /** D3 zoom behavior controlling pan/zoom within the photo viewer */
  protected _imgZoom: ZoomBehavior<Element, unknown>;
  /** Whether to display high-resolution images in the viewer */
  protected _hires: boolean;
  /** Tiler instance used to partition the viewport into tile requests */
  protected _tiler: Tiler;
  /** Next page number to fetch for each tile ID */
  protected _nextPage: Map<TileID, number>;
  /** Last viewport version that was loaded, to skip redundant updates */
  protected _lastv: number | null;


  /**
   * @param context - Global shared application context
   */
  public constructor(context: Context) {
    super(context);
    this.id = 'kartaview';
    this.requiredDependencies = new Set<SystemID>(['l10n', 'network', 'photos', 'spatial']);
    this.optionalDependencies = new Set<SystemID>(['gfx', 'ui']);
    this.autoStart = false;

    this._imgZoom = zoom()
      .extent([[0, 0], [320, 240]])
      .translateExtent([[0, 0], [320, 240]])
      .scaleExtent([1, 15]);

    this._hires = false;
    this._tiler = (new Tiler().zoomRange(TILEZOOM) as Tiler).skipNullIsland(true) as Tiler;
    this._nextPage = new Map<TileID, number>();
    this._lastv = null;

    // Ensure methods used as callbacks always have `this` bound correctly.
    this._keydown = this._keydown.bind(this);
    this._rotate = this._rotate.bind(this);
    this._step = this._step.bind(this);
    this._zoomPan = this._zoomPan.bind(this);
  }


  /**
   * Called after all core objects have been constructed.
   * @return  Promise resolved when this component has completed initialization
   */
  public initAsync(): Promise<void> {
    if (this._initPromise) return this._initPromise;

    return this._initPromise = super.initAsync()
      .then(() => this.resetAsync());
  }


  /**
   * Called after all core objects have been initialized.
   * @return  Promise resolved when this component has completed startup
   */
  public startAsync(): Promise<void> {
    if (this._startPromise) return this._startPromise;

    const context = this.context;
    const eventManager = context.systems.gfx?.eventManager;
    const ui = context.systems.ui;

    // add osc-wrapper
    const $wrapper: D3Selection = context.container().select('.photoviewer .middle-middle')
      .selectAll('.osc-wrapper')
      .data([0]);

    const $$wrapper: D3EnterSelection = $wrapper.enter()
      .append('div')
      .attr('class', 'photo-wrapper osc-wrapper')
      .classed('hide', true)
      .call(this._imgZoom.on('zoom', this._zoomPan) as any)
      .on('dblclick.zoom', null);

    // add .photo-footer
    const $$footer: D3EnterSelection = $$wrapper
      .append('div')
      .attr('class', 'photo-footer');

    $$footer
      .append('div')
      .attr('class', 'photo-options');

    $$footer
      .append('div')
      .attr('class', 'photo-attribution');


    // add .photo-controls
    const $$controls: D3EnterSelection = $$wrapper
      .append('div')
      .attr('class', 'photo-controls-wrap')
      .append('div')
      .attr('class', 'photo-controls');

    $$controls
      .append('button')
      .on('click.back', () => this._step(-1))
      .call(uiIcon('#fas-backward-step'));

    $$controls
      .append('button')
      .on('click.rotate-ccw', () => this._rotate(-90))
      .call(uiIcon('#fas-arrow-rotate-left'));

    $$controls
      .append('button')
      .on('click.rotate-cw', () => this._rotate(90))
      .call(uiIcon('#fas-arrow-rotate-right'));

    $$controls
      .append('button')
      .on('click.forward', () => this._step(1))
      .call(uiIcon('#fas-forward-step'));

    $$wrapper
      .append('div')
      .attr('class', 'osc-image-wrap');


    // Register viewer resize handler
    ui?.PhotoViewer.on('resize', (dimensions: Vec2) => {
      this._imgZoom = zoom()
        .extent([[0, 0], dimensions])
        .translateExtent([[0, 0], dimensions])
        .scaleExtent([1, 15])
        .on('zoom', this._zoomPan);
    });

    eventManager?.on('keydown', this._keydown);

    // don't need any async loading so resolve immediately
    this._started = true;
    return this._startPromise = Promise.resolve();
  }


  /**
   * Called after completing an edit session to reset any internal state
   * @return  Promise resolved when this component has completed resetting
   */
  public resetAsync(): Promise<void> {
    const context = this.context;
    const network = context.systems.network!;
    const spatial = context.systems.spatial!;

    network.clearMatching(id => id.startsWith('kartaview-') || id.includes(KARTAVIEW_API) || id.includes(OPENSTREETCAM_API));
    spatial.clearMatching(id => id.startsWith('kartaview-'));

    this._nextPage.clear();
    this._lastv = null;

    return Promise.resolve();
  }


  /**
   * Get already loaded image data that appears in the current map view
   * @return  Array of image data
   */
  public getImages(): MarkerData[] {
    const spatial = this.context.systems.spatial!;
    return spatial.getVisibleItems('kartaview-images').map(hit => hit.contents) as MarkerData[];
  }


  /**
   * Get already loaded sequence data that appears in the current map view
   * @return  Array of sequence data
   */
  public getSequences(): GeoJSONData[] {
    const spatial = this.context.systems.spatial!;
    return spatial.getVisibleItems('kartaview-sequences').map(hit => hit.contents) as GeoJSONData[];
  }


  /**
   * Schedule any data requests needed to cover the current map view
   */
  public loadTiles(): void {
    const context = this.context;
    const network = context.systems.network!;
    const viewport = context.viewport;

    if (this._lastv === viewport.v) return;  // exit early if the view is unchanged
    this._lastv = viewport.v;

    // Determine the tiles needed to cover the view..
    const tiles = this._tiler.getTiles(viewport).tiles;

    // Abort inflight requests that are no longer needed..
    const neededIDs = new Set<RequestID>(tiles.map(tile => `kartaview-tile-${tile.id}`));
    network.abortMatching(id => {
      const key = id.slice(0, id.lastIndexOf(','));  // requestID without page number
      return key.startsWith('kartaview-tile') && !neededIDs.has(key);
    });

    // Fetch files that are needed
    for (const tile of tiles) {
      this._loadNextTilePage(tile);
    }
  }


  /**
   * Load the next page of data for the given tile.
   * This uses `https://kartaview.org/1.0/list/nearby-photos/`
   * @param  tile - tile object
   */
  protected _loadNextTilePage(tile: Tile): void {
    const context = this.context;
    const network = context.systems.network!;

    const currZoom = context.viewport.transform.zoom;
    const maxPages = this._maxPageAtZoom(currZoom);
    const page = this._nextPage.get(tile.id) ?? 1;
    if (page > maxPages) return;

    const requestID = `kartaview-tile-${tile.id},${page}`;
    if (network.isCompleted(requestID) || network.isInflight(requestID)) return;

    const bbox = tile.wgs84Extent.bbox();
    const params = utilQsString({
      ipp: MAXRESULTS,
      page: page,
      bbTopLeft: [bbox.maxY, bbox.minX].join(','),
      bbBottomRight: [bbox.minY, bbox.maxX].join(','),
    }, true);

    const url = `${KARTAVIEW_API}/1.0/list/nearby-photos/`;
    network.fetch<any>(url, {
      requestID,
      method: 'POST',
      body: params,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    })
      .then(response => this._gotTile(tile, page, response))
      .catch(err => {
        if (err.name === 'AbortError') return;  // ok
        console.error(err);  // eslint-disable-line
      });
  }


  /**
   * Parse the response from the tile fetch
   * @param tile - The tile fetched
   * @param page - The page of data fetched
   * @param response - Response data
   */
  protected _gotTile(tile: Tile, page: number, response: any): void {
    const context = this.context;
    const gfx = context.systems.gfx;
    const spatial = context.systems.spatial!;

    const data = response?.currentPageItems || [];
    if (!data.length) return;

    const seenSequences = new Set<GeoJSONData>();

    // Process and cache the images
    for (const d of data) {
      const imageID = d.id.toString();
      const sequenceID = d.sequence_id.toString();

      // Note that this API call gives us the `username`, but not the image urls.
      // It also uses 'snake_case' instead of 'camelCase'.
      const image = this._cacheImage({
        id: imageID,
        sequenceID: sequenceID,
        loc: [+d.lng, +d.lat],
        ca: parseFloat(d.heading ?? d.headers),
        isPano: (d.field_of_view === '360'),
        captured_by: d.username,
        captured_at: (d.shot_date ?? d.date_added),
        sequenceIndex: parseInt(d.sequence_index, 10)
      });

      // Update the sequence to include this image, create if needed..
      const sequence = this._cacheSequence(image);
      seenSequences.add(sequence);
    }

    // Rebuild the geometry for the the seen sequences.
    // Update geometry in-place.. hope this is ok.
    for (const sequence of seenSequences) {
      const geojson = sequence.props.geojson as any;
      const imageIDs = sequence.props.imageIDs as PhotoID[];

      geojson.geometry.coordinates = imageIDs.map(imageID => {
        const image = spatial.getItem<KartaviewImage>('kartaview-images', imageID);
        return image?.loc;
      }).filter(Boolean);
      sequence.updateGeometry().touch();
      spatial.replaceData('kartaview-sequences', sequence);
    }

    gfx?.deferredRedraw();

    if (data.length === MAXRESULTS) {
      this._nextPage.set(tile.id, page + 1);
      this._loadNextTilePage(tile);
    } else {
      this._nextPage.set(tile.id, Infinity);   // loaded all available pages for this tile
    }
  }


  /**
   * Shows the photo viewer, and hides all other photo viewers
   */
  public showViewer(): void {
    const $viewer: D3Selection = this.context.container().select('.photoviewer')
      .classed('hide', false);

    const isHidden = $viewer.selectAll('.photo-wrapper.osc-wrapper.hide').size();

    if (isHidden) {
      $viewer
        .selectAll('.photo-wrapper:not(.osc-wrapper)')
        .classed('hide', true);

      $viewer
        .selectAll('.photo-wrapper.osc-wrapper')
        .classed('hide', false);
    }
  }


  /**
   * Hides the photo viewer and clears the currently selected image
   */
  public hideViewer(): void {
    const context = this.context;
    context.systems.photos!.selectPhoto(null);

    const $viewer: D3Selection = context.container().select('.photoviewer');
    $viewer
      .classed('hide', true)
      .selectAll('.photo-wrapper')
      .classed('hide', true);

    this.emit('imageChanged');
  }


  /**
   * Note:  most code should call `PhotoSystem.selectPhoto(layerID, photoID)` instead.
   * That will manage the state of what the user clicked on, and then call this function.
   * @param  imageID - the id of the image to select
   * @return  Promise that resolves to the image after it has been selected
   */
  public selectImageAsync(imageID: PhotoID | null): Promise<KartaviewImage | void> {
    if (!imageID) {
      this._updatePhotoFooter(null);  // reset
      return Promise.resolve();  // do nothing
    }

    const context = this.context;
    const spatial = context.systems.spatial!;

    return this.startAsync()
      .then(() => this._loadImageAsync(imageID))
      .then(image => {
        if (!image) return;

        const $wrapper: D3Selection = context.container().select('.photoviewer .osc-wrapper');
        const $imageWrap: D3Selection = $wrapper.selectAll('.osc-image-wrap');

        $wrapper
          .transition()
          .duration(100)
          .call(this._imgZoom.transform as any, zoomIdentity);

        $imageWrap
          .selectAll('.osc-image')
          .remove();

        const sequence = spatial.getItem<KartaviewSequence>('kartaview-sequences', image?.props?.sequenceID);
        const r = sequence?.props?.rotation ?? 0;

        $imageWrap
          .append('img')
          .attr('class', 'osc-image')
          .attr('src', this._hires ? (image.props.imageHighUrl ?? '') : (image.props.imageMedUrl ?? ''))
          .style('transform', `rotate(${r}deg)`);

        this._updatePhotoFooter(image.id);

        return image;  // pass the image to anything that chains off this Promise
      });
  }


  /**
   * Update the photo attribution section of the image viewer
   * @param  imageID - the new imageID
   */
  protected _updatePhotoFooter(imageID: PhotoID | null): void {
    const context = this.context;
    const l10n = context.systems.l10n!;
    const photos = context.systems.photos!;
    const spatial = context.systems.spatial!;
    const $wrapper: D3Selection = context.container().select('.photoviewer .osc-wrapper');

    // Options Section
    const $options: D3Selection = $wrapper.selectAll('.photo-options');

    // .hires checkbox
    let $label: D3Selection = $options.selectAll('.hires')
      .data([0]);

    // enter
    const $$label: D3EnterSelection = $label.enter()
      .append('label')
      .attr('for', 'osc-hires-input')
      .attr('class', 'hires');

    $$label
      .append('input')
      .attr('type', 'checkbox')
      .attr('id', 'osc-hires-input')
      .on('click', (e: PointerEvent) => {
        e.stopPropagation();

        this._hires = !this._hires;
        this.selectImageAsync(photos.currPhotoID);  // reselect
      });

    $$label
      .append('span');

    // update
    $label = $label.merge($$label);
    $label.selectAll('#osc-hires-input')
      .property('checked', this._hires);

    $label.selectAll('span')
      .text(l10n.t('photos.hires'));


    // Attribution Section
    const $attribution: D3Selection = $wrapper.selectAll('.photo-attribution').html('&nbsp;');  // clear DOM content

    const image = spatial.getItem<KartaviewImage>('kartaview-images', imageID!);
    if (!image) return;

    const props = image.props;

    if (props.captured_by) {
      $attribution
        .append('span')
        .attr('class', 'captured_by')
        .text(props.captured_by);

      $attribution
        .append('span')
        .text('|');
    }

    if (props.captured_at) {
      $attribution
        .append('span')
        .attr('class', 'captured_at')
        .text(l10n.displayShortDate(props.captured_at));

      $attribution
        .append('span')
        .text('|');
    }

    $attribution
      .append('a')
      .attr('class', 'image-link')
      .attr('target', '_blank')
      .attr('href', `https://kartaview.org/details/${props.sequenceID}/${props.sequenceIndex}/track-info`)
      .text('kartaview.org');
  }


  /**
   * How many pages of data should we fetch at different zooms?
   * The idea is that the user can zoom in more to see more images.
   * @param  z - zoom level
   * @return  max pages of data to fetch
   */
  protected _maxPageAtZoom(z: number): number {
    if (z < 15) return 2;
    if (z < 16) return 5;
    if (z < 17) return 10;
    if (z < 18) return 20;
    if (z < 19) return 40;
    return 80;
  }


  /**
   * Load a single image.
   * This uses `https://api.openstreetcam.org/2.0/photo/<imageID>`
   * If the image has not yet been fetched (for example if we are loading an image
   *  specified in the urlhash and we haven't loaded tiles yet) we will cache the image data also.
   * @param  imageID - the imageID to load
   * @return  Promise resolved with the image Object
   */
  protected _loadImageAsync(imageID: PhotoID): Promise<KartaviewImage | void> {
    const context = this.context;
    const gfx = context.systems.gfx;
    const network = context.systems.network!;
    const spatial = context.systems.spatial!;

    // If the image is already cached with an imageUrl, we can just resolve.
    // const image = cache.images.get(imageID);
    const image = spatial.getItem<KartaviewImage>('kartaview-images', imageID);
    if (image?.props?.imageLowUrl) {
      return Promise.resolve(image);  // fetched it already
    }

    const requestID = `kartaview-image-${imageID}`;
    const url = `${OPENSTREETCAM_API}/2.0/photo/${imageID}`;

    return network.fetch<any>(url, { requestID })
      .then(response => {
        const d = response?.result?.data;
        if (!d) throw new Error(`Image ${imageID} not found`);

        const sequenceID = d.sequenceId.toString();

        // Note that this API call gives us the image urls, but not the `username`.
        // It also uses 'camelCase' instead of 'snake_case'.
        const image = this._cacheImage({
          id:             imageID,
          sequenceID:     sequenceID,
          loc:            [+d.lng, +d.lat],
          ca:             parseFloat(d.heading ?? d.headers),
          isPano:         (d.fieldOfView === '360'),
          captured_at:    (d.shotDate ?? d.dateAdded),
          sequenceIndex:  parseInt(d.sequenceIndex, 10),
          imageLowUrl:    d.imageThUrl,     // thumbnail
          imageMedUrl:    d.imageLthUrl,    // large thumbnail
          imageHighUrl:   d.imageProcUrl    // full resolution
        });

        // Update the sequence to include this image, create if needed..
        const sequence = this._cacheSequence(image);

        // Rebuild the geometry for the the seen sequence.
        // Update geometry in-place.. hope this is ok.
        const geojson = sequence.props.geojson as any;
        const imageIDs = sequence.props.imageIDs as PhotoID[];

        geojson.geometry.coordinates = imageIDs.map(imageID => {
          const image = spatial.getItem<KartaviewImage>('kartaview-images', imageID);
          return image?.loc;
        }).filter(Boolean);

        sequence.updateGeometry().touch();
        spatial.replaceData('kartaview-sequences', sequence);
        gfx?.deferredRedraw();
        return image;
      })
      .catch(err => {
        if (err instanceof Error) console.error(err);  // eslint-disable-line no-console
      });
  }


  /**
   * Handler for zoom/pan events in the viewer.
   * The user can drag and zoom in on the image.
   * @param  e
   */
  protected _zoomPan(e: any): void {
    const t = e.transform;
    const $container: D3Selection = this.context.container();
    const $imageWrap: D3Selection = $container.select('.photoviewer .osc-image-wrap');

    if ($imageWrap.size()) {
      utilSetTransform($imageWrap.node() as HTMLElement, t.x, t.y, t.k);
    }
  }


  /**
   * Rotate the sequence in the viewer.
   * The user can press buttons to rotate the image if it has been recorded sideways.
   * @param  deg - degrees to rotate
   */
  protected _rotate(deg: number): void {
    const context = this.context;
    const photos = context.systems.photos!;
    const spatial = context.systems.spatial!;

    const image = spatial.getItem<KartaviewImage>('kartaview-images', photos.currPhotoID!);
    if (!image) return;

    const sequence = spatial.getItem<KartaviewSequence>('kartaview-sequences', image.props?.sequenceID as string);
    if (!sequence) return;

    let r: number = sequence.props?.rotation ?? 0;
    r += deg;

    if (r > 180) r -= 360;
    if (r < -180) r += 360;
    sequence.props.rotation = r;  // Update properties in-place.. hope this is ok.

    const $wrapper: D3Selection = context.container().select('.photoviewer .osc-wrapper');

    $wrapper
      .transition()
      .duration(100)
      .call(this._imgZoom.transform as any, zoomIdentity);

    $wrapper.selectAll('.osc-image')
      .transition()
      .duration(100)
      .style('transform', `rotate(${r}deg)`);
  }


  /**
   * Handler for keydown events on the window, but only if the photo viewer is visible.
   * @param  e - A DOM KeyboardEvent
   */
  protected _keydown(e: KeyboardEvent): void {
    const context = this.context;
    const eventManager = context.systems.gfx?.eventManager;
    const photos = context.systems.photos!;

    // Test environment?
    if (!eventManager) return;
    // Ignore keypresses unless we actually have a Mapillary photo showing
    if (!photos.isViewerShowing() || photos.currPhotoLayerID !== 'kartaview') return;
    // Ignore modified keypresses (user might be panning or rotating)
    if (eventManager.modifierKeys.size) return;

    // Only allow key navigation if the user doesn't have something
    // more important focused - like a input, textarea, menu, etc.
    const activeElement = document.activeElement?.tagName ?? 'BODY';
    if (activeElement !== 'BODY') return;

    if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      this._step(-1);
    } else if (e.key === 'ArrowUp' || e.key === 'ArrowRight') {
      this._step(1);
    }
  }


  /**
   * Step forward/backward along the sequence in the viewer.
   * @param  stepBy - number to step by, either +1 or -1
   */
  protected _step(stepBy: number): void {
    const context = this.context;
    const photos = context.systems.photos!;
    const spatial = context.systems.spatial!;

    const image = spatial.getItem<KartaviewImage>('kartaview-images', photos.currPhotoID!);
    if (!image) return;

    const sequence = spatial.getItem<KartaviewSequence>('kartaview-sequences', image.props?.sequenceID as string);
    if (!sequence) return;

    const nextIndex = (image.props.sequenceIndex ?? 0) + stepBy;
    const nextImageID = sequence.props.imageIDs?.[nextIndex];
    if (!nextImageID) return;

    photos.selectPhoto('kartaview', nextImageID);

    this.emit('imageChanged');
  }


  /**
   * Store the given image in the caches
   * @param  source - the image properties
   * @return  The image
   */
  protected _cacheImage(source: ImageSource): KartaviewImage {
    const context = this.context;
    const spatial = context.systems.spatial!;
    const imageID = source.id;

    let image = spatial.getItem<KartaviewImage>('kartaview-images', imageID);
    if (!image) {
      const loc = spatial.getFreeLoc('kartaview-images', source.loc);
      image = new MarkerData<KartaviewImageProps>(context, {
        type:       'photo',
        serviceID:  this.id as ServiceID,
        id:         imageID,
        loc:        loc
      });
    }

    // Allow 0, but not things like NaN, null, Infinity
    const caIsNumber = Number.isFinite(source.ca);
    const indexIsNumber = Number.isFinite(source.sequenceIndex);

    // Update whatever additional props we were passed..
    const props = image.props;
    if (source.sequenceID)     props.sequenceID     = source.sequenceID;
    if (indexIsNumber)         props.sequenceIndex  = source.sequenceIndex;
    if (source.captured_at)    props.captured_at    = source.captured_at;
    if (source.captured_by)    props.captured_by    = source.captured_by;
    if (caIsNumber)            props.ca             = source.ca;
    if (source.isPano)         props.isPano         = source.isPano;
    if (source.imageLowUrl)    props.imageLowUrl    = source.imageLowUrl;   // thumbnail
    if (source.imageMedUrl)    props.imageMedUrl    = source.imageMedUrl;   // large thumbnail
    if (source.imageHighUrl)   props.imageHighUrl   = source.imageHighUrl;  // full resolution

    if (!props.isPano)  props.isPano = false;
    spatial.replaceData('kartaview-images', image);

    return image.touch();
  }


  /**
   * Store the given sequence in the caches.
   * Sequence data is always derived from the image data.
   * @param  image - the image that belongs to this sequence
   * @return  The sequence
   */
  protected _cacheSequence(image: KartaviewImage): KartaviewSequence {
    const context = this.context;
    const spatial = context.systems.spatial!;
    const sequenceID = image.props.sequenceID;
    const sequenceIndex = image.props.sequenceIndex ?? 0;

    let sequence = spatial.getItem<KartaviewSequence>('kartaview-sequences', sequenceID);
    if (!sequence) {
      sequence = new GeoJSONData<KartaviewSequenceProps>(context, {
        id:         sequenceID,
        type:       'sequence',
        serviceID:  this.id as ServiceID,
        imageIDs:   [],
        rotation:   0,
        firstIndex: Infinity,
        geojson: {
          type: 'Feature',
          properties: {},
          geometry: {
            type: 'LineString',
            coordinates: []
          }
        } as GeoJSON.Feature
      });
    }

    // Update sequence properties as needed.
    const props = sequence.props;

    // Insert image into sequence - note that `imageIDs` may be a sparse array.
    props.imageIDs![sequenceIndex] = image.id;

    // Set metadata for this sequence according to the earliest image.
    if (sequenceIndex < (props.firstIndex ?? Infinity)) {
      props.firstIndex  = sequenceIndex;
      props.isPano      = image.props.isPano;
      props.captured_at = image.props.captured_at;
      props.captured_by = image.props.captured_by;
    }

    spatial.replaceData('kartaview-sequences', sequence);

    return sequence.touch();
  }

}
