import { selection } from 'd3-selection';
import { geoArea, geoLength, geoCentroid } from 'd3-geo';
import geojsonRewind from '@mapbox/geojson-rewind';
import { Extent, geoSphericalDistance } from '@rapid-sdk/math';
import { utilGetAllNodes } from '@rapid-sdk/util';

import { AbstractUiCard } from './AbstractUiCard.ts';
import { MarkerData } from '../../data/MarkerData.ts';
import { uiIcon } from '../icon.ts';
import { utilCmd } from '../../util/cmd.ts';

import type { Context } from '../../Context.ts';
import type { D3Selection } from 'd3-selection';


// using WGS84 authalic radius (6371007.1809 m)
function radiansToMeters(r: number): number {
  return r * 6371007.1809;
}

// http://gis.stackexchange.com/a/124857/40446
function steradiansToSqmeters(r: number): number {
  return r / (4 * Math.PI) * 510065621724000;
}


function asLineString(feature: any): any {
  const geom = feature.geometry;
  if (geom.type === 'LineString') return geom;

  // get an outer ring
  const result: any = { type: 'LineString', coordinates: [] };
  if (geom.type === 'Polygon') {
    result.coordinates = geom.coordinates[0];
  } else if (geom.type === 'MultiPolygon') {
    result.coordinates = geom.coordinates[0][0];
  }

  return result;
}


/**
 * `UiMeasurementCard` shows measurements (length, area, distance, coordinates) for the selection.
 */
export class UiMeasurementCard extends AbstractUiCard {
  public id: string;

  protected _isImperial: boolean;
  protected _keys: string[] | null;


  /**
   * @param  context - Global shared application context
   */
  public constructor(context: Context) {
    super(context);
    this.id = 'measurement';

    const gfx = context.systems.gfx!;
    const l10n = context.systems.l10n!;

    this._isImperial = !l10n.isMetric;
    this._keys = null;

    // Ensure methods used as callbacks always have `this` bound correctly.
    // (This is also necessary when using `d3-selection.call`)
    this.render = this.render.bind(this);
    this._setupKeybinding = this._setupKeybinding.bind(this);

    // Event listeners
    gfx.on('draw', this.render);
    context.on('modechange', this.render);
    l10n.on('localechange', this._setupKeybinding);

    this._setupKeybinding();
  }


  /**
   * Accepts a parent selection, and renders the content under it.
   * (The parent selection is required the first time, but can be inferred on subsequent renders)
   * @param $parent - A d3-selection to a HTMLElement that this component should render itself into
   */
  public override render($parent: D3Selection | null = this.$parent): void {
    if ($parent instanceof selection) {
      this.$parent = $parent;
    } else {
      return;   // no parent - called too early?
    }

    if (!this.visible) return;

    const context = this.context;
    const l10n = context.systems.l10n!;
    const graph = context.systems.editor!.staging.graph;
    const localeCode = l10n.localeCode;

    // .card-container
    let $wrap: D3Selection = $parent.selectAll('.card-container')
      .data([this.id], d => d);

    // enter
    const $$wrap = $wrap.enter()
      .append('div')
      .attr('class', d => `fillD2 card-container card-container-${d}`);

    const $$title = $$wrap
      .append('div')
      .attr('class', 'fillD2 card-title');

    $$title
      .append('h3');

    $$title
      .append('button')
      .attr('class', 'close')
      .on('click', this.toggle)
      .call(uiIcon('#rapid-icon-close'));

    $$wrap
      .append('div')
      .attr('class', d => `card-content card-content-${d}`);


    // update
    this.$wrap = $wrap = $wrap.merge($$wrap);

    $wrap.selectAll('h3')
      .text(l10n.t('info_panels.measurement.title'));


    // .card-content
    const $content = $wrap.selectAll('.card-content');

    // Empty out the DOM content and rebuild from scratch..
    $content.html('');

    let heading: string | undefined;
    let center: any, location: any, centroid: any;
    let isClosed: boolean | null | undefined, geometry: string | null | undefined;
    let totalNodeCount: number | undefined;
    let length = 0;
    let area = 0;
    let distance: number | undefined;

    const selectedIDs = context.selectedIDs();
    const selectedData = context.selectedData();
    const [selectedItem] = selectedData.values();  // first item
    const isNote = (selectedItem instanceof MarkerData && selectedItem.serviceID === 'osm');

    if (selectedData.size === 1 && isNote) {   // selected 1 OSM Note
      const note = selectedItem;
      heading = l10n.t('text.note') + ' ' + note.id;
      location = note.loc;
      geometry = 'note';

    } else {  // selected 0…n OSM Entities
      const selected = selectedIDs.map(id => graph.hasEntity(id)).filter(Boolean) as any[];

      if (selected.length === 1) {
        heading = selected[0].id;
      } else {
        heading = l10n.t('info_panels.selected', { n: selected.length });
      }

      if (selected.length > 0) {    // 1…n
        const allExtent = new Extent();

        for (const entity of selected) {
          const extent = entity.extent(graph);
          const geojson = geojsonRewind(entity.asGeoJSON(graph), true);  // true = outer ring clockwise (how D3 wants it)

          allExtent.extendSelf(extent);
          geometry = entity.geometry(graph);

          if (geometry === 'line' || geometry === 'area') {
            isClosed = (entity.type === 'relation') || (entity.isClosed() && !entity.isDegenerate());

            length += radiansToMeters(geoLength(asLineString(geojson)));

            centroid = geoCentroid(geojson);
            if (!centroid  || !isFinite(centroid[0]) || !isFinite(centroid[1])) {
              centroid = extent.center();
            }

            if (isClosed) {
              area += steradiansToSqmeters(geoArea(geojson));
            }
          }
        }

        if (selected.length > 1) {  // 2…n
          geometry = null;
          isClosed = null;
          centroid = null;
        }

        if (selected.length === 2 && selected[0].type === 'node' && selected[1].type === 'node') {
          distance = geoSphericalDistance(selected[0].loc, selected[1].loc);
        }

        if (selected.length === 1 && selected[0].type === 'node') {
          location = selected[0].loc;
        } else {
          totalNodeCount = utilGetAllNodes(selectedIDs, graph).length;
        }

        if (!location && !centroid) {
          center = allExtent.center();
        }
      }
    }


    if (heading) {
      $content
        .append('h4')
        .attr('class', 'measurement-heading')
        .text(heading);
    }

    const $list = $content.append('ul');
    let $item: D3Selection;

    if (geometry) {
      $list
        .append('li')
        .text(l10n.t('info_panels.measurement.geometry') + ':')
        .append('span')
        .text(isClosed ? l10n.t('info_panels.measurement.closed_' + geometry) : l10n.t('geometry.' + geometry));
    }

    if (totalNodeCount) {
      $list
        .append('li')
        .text(l10n.t('info_panels.measurement.node_count') + ':')
        .append('span')
        .text(totalNodeCount.toLocaleString(localeCode));
    }

    if (area) {
      $list
        .append('li')
        .text(l10n.t('info_panels.measurement.area') + ':')
        .append('span')
        .text(l10n.displayArea(area, this._isImperial));
    }

    if (length) {
      $list
        .append('li')
        .text(l10n.t('info_panels.measurement.' + (isClosed ? 'perimeter' : 'length')) + ':')
        .append('span')
        .text(l10n.displayLength(length, this._isImperial));
    }

    if (typeof distance === 'number') {
      $list
        .append('li')
        .text(l10n.t('info_panels.measurement.distance') + ':')
        .append('span')
        .text(l10n.displayLength(distance, this._isImperial));
    }

    if (location) {
      $item = $list
        .append('li')
        .text(l10n.t('info_panels.measurement.location') + ':');
      $item.append('span')
        .text(l10n.dmsCoordinatePair(location));
      $item.append('span')
        .text(l10n.decimalCoordinatePair(location));
    }

    if (centroid) {
      $item = $list
        .append('li')
        .text(l10n.t('info_panels.measurement.centroid') + ':');
      $item.append('span')
        .text(l10n.dmsCoordinatePair(centroid));
      $item.append('span')
        .text(l10n.decimalCoordinatePair(centroid));
    }

    if (center) {
      $item = $list
        .append('li')
        .text(l10n.t('info_panels.measurement.center') + ':');
      $item.append('span')
        .text(l10n.dmsCoordinatePair(center));
      $item.append('span')
        .text(l10n.decimalCoordinatePair(center));
    }

    // Add Imperial/Metric toggle
    if (length || area || typeof distance === 'number') {
      const toggle = this._isImperial ? 'imperial' : 'metric';
      $content
        .append('a')
        .text(l10n.t(`info_panels.measurement.${toggle}`))
        .attr('href', '#')
        .attr('class', 'button button-toggle-units')
        .on('click', (e: PointerEvent) => {
          e.preventDefault();
          this._isImperial = !this._isImperial;
          this.render();
        });
    }
  }


  /**
   * This sets up the keybinding, replacing existing if needed
   */
  protected _setupKeybinding(): void {
    const context = this.context;
    const keybinding = context.keybinding();
    const l10n = context.systems.l10n!;

    if (Array.isArray(this._keys)) {
      keybinding.off(this._keys);
    }

    this._keys = [utilCmd('⌘⇧' + l10n.t('shortcuts.command.toggle_measurement_card.key'))];
    context.keybinding().on(this._keys, this.toggle);
  }

}
