import * as PIXI from 'pixi.js';
import { AtlasAllocator, registerAtlasUploader } from './lib/AtlasAllocator.ts';

import type { AtlasOptions } from './lib/AtlasAllocator.ts';
import type { Context } from '../Context.ts';
import type { GraphicsSystem } from '../core/GraphicsSystem.ts';


/**
 * Convenience type for texture key.
 * These identifiers look like `${atlasID}-${textureID}`
 */
type TextureKey = string;

/** Atlas collection containing symbol, text, and tile atlases */
type AtlasCollection = Record<AtlasID, AtlasAllocator>;

/** Tracked texture data with refcount */
interface TextureData {
  texture: PIXI.Texture;
  refcount: number;
}

/** DashLine texture cache */
type DashTextureCache = Record<string, PIXI.Texture>;


/**
 * PixiTextures does the work of managing the textures.
 * We store most textures in 3 atlases, each one is for holding similar sized things.
 * Each "atlas" manages its own store of "TextureSources" - real textures that upload to the GPU.
 * This helps pack them efficiently and avoids swapping textures frequently as WebGL draws the scene.
 *
 * Properties available:
 * - `loaded`   `true` after the patterns have finished loading
 */
export class PixiTextures {

  /** Reference to the owning GraphicsSystem */
  public gfx: GraphicsSystem;
  /** Global shared application context */
  public context: Context;
  /** Whether all pattern textures have been loaded and the manager is ready */
  public loaded: boolean;

  /** The active texture atlas collection (small / medium / large bins) */
  protected _atlas: AtlasCollection | null;
  /** All named textures keyed by a unique string (e.g. 'symbol-boldPin') */
  protected _textureData: Map<TextureKey, TextureData>;
  /** SVG symbol elements (or null if failed) keyed by icon name (e.g. 'temaki-school') */
  protected _svgIcons: Map<TextureID, SVGSymbolElement | null>;
  /** Cached textures used by the DashLine plugin, keyed by dash pattern string */
  protected _dashTextureCache: DashTextureCache;


  /**
   * @param gfx - The GraphicsSystem that owns the texture manager
   */
  public constructor(gfx: GraphicsSystem) {
    this.gfx = gfx;
    this.context = gfx.context;

    this.loaded = false;

    // We store textures in 3 atlases, each one is for holding similar sized things. See `reset()` below.
    // Each "atlas" manages its own store of "TextureSources" - real textures that upload to the GPU.
    // This helps pack them efficiently and avoids swapping textures frequently as WebGL draws the scene.
    this._atlas = null;

    // All the named textures we know about.
    // Each mapping is a unique identifying key to a PIXI.Texture
    // The Texture is not necessarily packed in an Atlas (but ideally it should be)
    // Important!  Make sure these texture keys don't conflict
    this._textureData = new Map<TextureKey, TextureData>();  // (e.g. 'symbol-boldPin')

    // Because SVGs take some time to texturize, store the svg data and texturize only if needed
    this._svgIcons = new Map<TextureID, SVGSymbolElement | null>();  // (e.g. 'temaki-school')

    // DashLine plugin needs its own cache - we could eventually put these in an atlas.
    this._dashTextureCache = {};

    // Prepare a "bundle" to load the pattern textures
    const assets = this.context.systems.assets!;
    const filenames = [
      'bushes', 'cemetery', 'cemetery_buddhist', 'cemetery_christian', 'cemetery_jewish', 'cemetery_muslim',
      'construction', 'dots', 'farmland', 'farmyard', 'forest', 'forest_broadleaved', 'forest_leafless',
      'forest_needleleaved', 'grass', 'landfill', 'lines', 'orchard', 'pond', 'quarry', 'vineyard',
      'waves', 'wetland', 'wetland_bog', 'wetland_marsh', 'wetland_reedbed', 'wetland_swamp'
    ];
    const bundle: Record<string, string> = {};
    for (const k of filenames) {
      bundle[k] = assets.getFileURL(`img/pattern/${k}.png`);
    }

    PIXI.Assets.addBundle('patterns', bundle);

    this.reset();
  }


  /**
   * Replace any Pixi objects and internal state.
   */
  public reset(): void {
    const gfx = this.gfx;
    if (!gfx.pixi) return;  // called too soon?

    // Before using the atlases, we need to register the upload function with the renderer.
    // This will choose the correct function for either webGL or webGPU renderer type.
    const renderer = gfx.pixi.renderer;
    registerAtlasUploader(renderer);

    // Try to determine a reasonable the max texture size.
    // We will prefer large size of 8192 to avoid texture swapping, but can settle for less.
    const trySize = 8192;
    let maxSize = 2048;   // a reasonable default
    let useCanvas = false;
    if (gfx.highQuality) {
      if (renderer.type === PIXI.RendererType.WEBGL) {
        const gl = (renderer as PIXI.WebGLRenderer).gl;
        maxSize = gl.getParameter(gl.MAX_TEXTURE_SIZE);
      } else if (renderer.type === PIXI.RendererType.WEBGPU) {
        const gpu = (renderer as PIXI.WebGPURenderer).gpu;
        maxSize = gpu.adapter.limits.maxTextureDimension2D;
      } else if (renderer.type === PIXI.RendererType.CANVAS) {
        maxSize = trySize;
        useCanvas = true;
      }
    }
    const options: AtlasOptions = {
      size: Math.min(trySize, maxSize),
      useCanvas: useCanvas
    };

    // We store textures in 3 atlases, each one is for holding similar things.
    // Each "atlas" manages its own store of "TextureSources" - real textures that upload to the GPU.
    // This helps pack them efficiently and avoids swapping textures frequently as WebGL draws the scene.
    this._atlas = {
      symbol: new AtlasAllocator({ label: 'symbol', ...options }),  // small graphics - markers, pins, symbols
      text: new AtlasAllocator({ label: 'text', ...options }),      // text labels
      tile: new AtlasAllocator({ label: 'tile', ...options })       // 256 or 512px square imagery tiles
    };

    this._textureData.clear();
    this._svgIcons.clear();
    this._dashTextureCache = {};

    this._cacheGraphics();

    // Replace or load patterns
    Promise.resolve()
      .then(() => {
        // If they've been loaded before, force-unload them to get new Textures.
        // This might happen after a WebGL context loss.
        if (this.loaded) {
          PIXI.Assets.unloadBundle(['patterns']);
          this.loaded = false;
        }
      })
      .then(() => PIXI.Assets.loadBundle(['patterns']))
      .then(result => {
        // note that we can't pack patterns into an atlas yet - see PixiFeaturePolygon.ts
        for (const [textureID, texture] of Object.entries(result.patterns)) {
          this._textureData.set(textureID, { texture: texture as PIXI.Texture, refcount: 1 });
        }
//        // if we could...
//        for (const [textureID, texture] of Object.entries(result.patterns)) {
//          const w = texture.baseTexture.width;
//          const h = texture.baseTexture.height;
//          const source = texture.baseTexture.resource.source;
//          this.allocate('symbol', textureID, w, h, source);
//        }

        this.loaded = true;
      })
      .catch(e => console.error(e));  // eslint-disable-line no-console
  }


  /**
   * Returns a cached texture by atlas and texture ID, converting SVG icons on demand.
   * @param atlasID - One of 'symbol', 'text', or 'tile'
   * @param textureID - e.g. 'boldPin', 'Main Street-normal', 'Bing-0,1,2'
   * @returns The texture (or `null` if not found)
   */
  public getTexture(atlasID: AtlasID, textureID: TextureID): PIXI.Texture | null {
    const key = `${atlasID}-${textureID}`;
    const tdata = this._textureData.get(key);

    if (tdata) return tdata.texture;

    // Is this an svg icon that we haven't converted to a texture yet?
    if (this._svgIcons.has(textureID)) {
      this._svgIconToTexture(textureID);
      return PIXI.Texture.EMPTY;   // return a placeholder
    }

    return null;
  }


  /**
   * These are just like any other texture except that they can't live in an atlas.
   * PixiFeaturePolygon.ts has some comments on it, maybe a Pixi bug or limitation.
   * @param textureID - e.g. 'bushes'
   * @returns The texture (or `undefined` if not found)
   */
  public getPatternTexture(textureID: TextureID): PIXI.Texture | undefined {
    const tdata = this._textureData.get(textureID);
    return tdata?.texture;
  }


  /**
   * Returns a texture rendering the first slab of the given atlas, for debugging.
   * @param atlasID - One of 'symbol', 'text', or 'tile'
   * @returns Texture for the specified atlas
   * @throws Throws if passed an invalid atlasID
   */
  public getDebugTexture(atlasID: AtlasID): PIXI.Texture | null {
    const atlas = this._atlas && this._atlas[atlasID];
    if (!atlas) {
      throw new Error(`Unknown atlasID "${atlasID}"`);
    };

    const source = atlas.slabs[0];
    if (!source) return null;

    return new PIXI.Texture({ source: source });
  }


  /**
   * This packs an asset into one of the atlases and tracks it in the textureData map.
   *
   * The asset must be one of:  `ImageData | Uint8ClampedArray | HTMLCanvasElement | HTMLImageElement | ImageBitmap`
   *
    * For non-ImageData sources (canvas, bitmap, image) the asset is handed directly
    * to the atlas allocator and uploaded to the GPU via `texSubImage2D` - no
    * intermediate `getImageData` readback happens.  Non-tile `ImageBitmap` callers
    * must keep the bitmap alive until upload; tile bitmaps are copied into the
    * edge-padded canvas before this method returns.
   *
   * For the **tile** atlas only, the asset is first drawn onto a slightly oversized
   * canvas with edge-replicated padding so that neighbor tiles don't bleed across
   * each other's rect boundaries under bilinear sampling (see issue Rapid#1650).
   * Symbols / text / icons don't need this - they already fade to transparent at
   * their edges - so they're uploaded as-is with a 1px transparent ring.
   *
   * @param atlasID - One of 'symbol', 'text', or 'tile'
   * @param textureID - e.g. 'boldPin', 'Main Street-normal', 'Bing-0,1,2'
   * @param width - width in pixels
   * @param height - height in pixels
   * @param asset - The thing to pack
   * @param textureOptions - optional options to pass to Pixi when creating the texture.
   * @returns The newly allocated texture (or `null` if it couldn't be packed)
   * @throws Throws if passed an invalid atlasID or if allocation failed for some other reason
   */
  public allocate(
    atlasID: AtlasID,
    textureID: TextureID,
    width: number,
    height: number,
    asset: ImageData | Uint8ClampedArray | HTMLCanvasElement | HTMLImageElement | ImageBitmap,
    textureOptions?: PIXI.TextureOptions
  ): PIXI.Texture | null {

    const atlas = this._atlas && this._atlas[atlasID];
    if (!atlas) {
      throw new Error(`Unknown atlasID "${atlasID}"`);
    };

    const key = `${atlasID}-${textureID}`;
    const tdata = this._textureData.get(key);

    // We've already allocated this texture in an atlas..
    // Increment the refcount and return it.
    if (tdata) {
      tdata.refcount++;
      return tdata.texture;
    }

    // Normalize the asset to something the atlas allocator can upload directly.
    // `ImageData` and `Uint8ClampedArray` are CPU pixel buffers - the allocator
    // can hand them to `texSubImage2D` as-is.
    // Canvas / image / bitmap sources are uploaded directly to the GPU.
    let source: ImageData | HTMLCanvasElement | HTMLImageElement | ImageBitmap;
    let padded = false;

    if (asset instanceof ImageData) {
      source = asset;

    } else if (asset instanceof Uint8ClampedArray) {
      // Cast needed because TypeScript thinks buffer could be SharedArrayBuffer
      source = new ImageData(asset as Uint8ClampedArray<ArrayBuffer>, width, height);

    } else if (asset instanceof HTMLCanvasElement || asset instanceof HTMLImageElement ||
               (typeof ImageBitmap !== 'undefined' && asset instanceof ImageBitmap)) {
      // Tiles need edge replication to avoid seams between adjacent tiles.
      // For other atlases the 1px ring stays transparent, which is fine for icons/text.
      if (atlasID === 'tile') {
        source = this._fromEdgePaddedCanvas(asset, width, height);
        padded = true;
      } else {
        source = asset;
      }

    } else {
      return null;  // some other format?
    }

    const texture = atlas.allocate(source, width, height, padded, textureOptions);
    if (!texture) {
      throw new Error(`Couldn't allocate texture ${key}`);
    }

    texture.label = key;

    this._textureData.set(key, { texture: texture, refcount: 1 });

    return texture;
  }


  /**
   * Builds a `(width + 2) x (height + 2)` canvas with the source drawn in the center
   * and a 1px edge-replicated ring around it.
   *
   * Used for tile imagery to prevent color bleed between neighboring atlas entries
   * under bilinear sampling (see issue Rapid#1650).  We use a two-pass `drawImage`:
   * first stretched to fill the ring (which puts approximately-edge colors in the
   * border pixels), then redrawn at the correct scale to keep the interior pixel-perfect.
   *
   * @param source - The source to pad
   * @param w - Inner width (the source's native size)
   * @param h - Inner height
   * @return A new canvas of size `(w+2) x (h+2)` with the padded image
   */
  protected _fromEdgePaddedCanvas(source: CanvasImageSource, w: number, h: number): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = w + 2;
    canvas.height = h + 2;
    const ctx = canvas.getContext('2d')!;
    ctx.drawImage(source, 0, 0, w + 2, h + 2);  // stretched: approximates edge colors in the ring
    ctx.drawImage(source, 1, 1, w, h);          // pixel-perfect center, overdraws the stretched copy
    return canvas;
  }


  /**
   * Unpacks a texture from the atlas and frees its resources
   * @param atlasID - One of 'symbol', 'text', or 'tile'
   * @param textureID - e.g. 'boldPin', 'Main Street-normal', 'Bing-0,1,2'
   * @throws Throws if passed an invalid atlasID
   */
  public free(atlasID: AtlasID, textureID: TextureID): void {
    const atlas = this._atlas && this._atlas[atlasID];
    if (!atlas) {
      throw new Error(`Unknown atlasID "${atlasID}"`);
    };

    const key = `${atlasID}-${textureID}`;
    const tdata = this._textureData.get(key);
    if (!tdata) return;  // free without allocate

    tdata.refcount--;

    if (tdata.refcount === 0) {
      atlas.free(tdata.texture);
      tdata.texture.destroy(false);   // false = don't destroy textureSource
      tdata.texture = null!;
      this._textureData.delete(key);
    }
  }


  /**
   * Convert frequently used graphics to textures for performance.
   * https://stackoverflow.com/questions/50940737/how-to-convert-a-graphic-to-a-sprite-in-pixijs
   *
   * The "container" can be any drawable Pixi object: a Container, Graphic, Mesh, Text, etc.
   * For example, rather than drawing a pin, we draw a square with a pin texture on it.
   * This is much more performant than drawing the graphics.
   *
   * We also pack these graphics into a "texture atlas" so that they all live in the same
   * TextureSource.  This texture gets sent to the GPU once then reused, so WebGL isn't constantly
   * swapping between textures as it draws things.
   *
   * @param atlasID - One of 'symbol', 'text', or 'tile'
   * @param textureID - Texture identifier (e.g. 'boldPin')
   * @param container - A PIXI.Container (or derived class) to convert to a texture (will be destroyed)
   * @param options - Options passed to `renderer.generateTexture`
   * @returns A Texture allocated from the requested texture atlas
   * @throws Throws if passed an invalid atlasID
   */
  public createTexture(
    atlasID: AtlasID,
    textureID: TextureID,
    container: PIXI.Container,
    options: Partial<PIXI.GenerateTextureOptions> = {}
  ): PIXI.Texture | null {
    if (!this.gfx.pixi) return null;  // called too soon?

    const atlas = this._atlas && this._atlas[atlasID];
    if (!atlas) {
      throw new Error(`Unknown atlasID "${atlasID}"`);
    };

    const generateTextureOptions: PIXI.GenerateTextureOptions = {
      ...options,
      antialias: false,
      target: container
    };

    const renderer = this.gfx.pixi.renderer;
    const temp = renderer.generateTexture(generateTextureOptions);
    const { pixels, width, height } = renderer.texture.getPixels(temp);   // a Uint8ClampedArray

    // The generated texture may be overscaled, but the `orig` Rectangle stores the original width/height
    // (i.e. the dimensions that a PIXI.Sprite using this texture will want to make itself)
    const textureOptions: PIXI.TextureOptions = {
      orig: temp.orig.clone()
    };

    const texture = this.allocate(atlasID, textureID, width, height, pixels, textureOptions);

    temp.destroy();
    container.destroy({ context: true });
    return texture;
  }


  /**
   * Because SVGs take some time to rasterize, store a placeholder and only rasterize when needed
   * @param textureID - Icon identifier (e.g. 'temaki-school')
   * @param symbol - The SVG Symbol element for the icon
   */
  public registerSvgIcon(textureID: TextureID, symbol: SVGSymbolElement): void {
    this._svgIcons.set(textureID, symbol);
  }


  /**
   * Converts a registered SVG icon into a texture and caches it.
   * @param textureID - Icon identifier (e.g. 'temaki-school')
   */
  protected _svgIconToTexture(textureID: TextureID): void {
    const symbol = this._svgIcons.get(textureID);
    if (!symbol) return;

    // Remove it to ensure that we only do this once.
    this._svgIcons.set(textureID, null);

// The old way, just put the SVG on an Image and pack that into the atlas.
// see https://github.com/facebook/Rapid/commit/dd24e912

    const viewBox = symbol.getAttribute('viewBox');

    // Somewhat large, but some Mapillary signs have a lot of detail/text in them
    const size = this.gfx.highQuality ? 64 : 32;

    // Make a new <svg> container
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('xmlns:xlink', 'http://www.w3.org/1999/xlink');
    svg.setAttribute('width', String(size));
    svg.setAttribute('height', String(size));
    svg.setAttribute('color', '#fff');   // white so we can tint them
    if (viewBox) {
      svg.setAttribute('viewBox', viewBox);
    }

    // Clone children (this is essentially what <use> does)
    for (const child of symbol.childNodes) {
      svg.appendChild(child.cloneNode(true));  // true = deep clone
    }

    const svgStr = (new XMLSerializer()).serializeToString(svg);

    let image = new Image();
    image.src = `data:image/svg+xml,${encodeURIComponent(svgStr)}`;
    image.onload = () => {
      const w = image.naturalWidth;
      const h = image.naturalHeight;
      this.allocate('symbol', textureID, w, h, image);
      this._svgIcons.delete(textureID);
      this.gfx.deferredRedraw();
      image = null!;
    };

// various approaches using the new Pixi SVG Parser and texture generation:
//    let svgString = this._svgIcons.get(textureID);
//    if (!svgString) return;
//
//     // Create a new graphics instance from the svg String,
//     // but first, sanitize the string to remove any 'currentColor', 'inherit', and 'url()' references.
//     svgString = svgString.replace(/(inherit|currentColor|url\(.*\))/gi, '#fff');
//     const size = 32;
//     const graphics = new PIXI.Graphics().svg(svgString);
//     graphics.setSize(size, size);
//
//     // Now, make a canvas and render the svg into it at higher resolution.
//     const renderer = this.gfx.pixi.renderer;
//     // const canvas = renderer.extract.canvas({ resolution: 2, target: svgGraphics });
//     const texture = renderer.textureGenerator.generateTexture({ resolution: 2, target: graphics });
// //    const canvas = renderer.texture.generateCanvas(texture);
// //    this.allocate('symbol', textureID, canvas.width, canvas.height, canvas);
//     const { pixels, width, height } = renderer.texture.getPixels(texture);
//     this.allocate('symbol', textureID, width, height, pixels);
//
//     texture.destroy();
//     graphics.destroy({ context: true });
//
//    this._svgIcons.delete(textureID);
//    this.gfx.deferredRedraw();
  }


  /**
   * Convert frequently used graphics to textures/sprites for performance
   * https://stackoverflow.com/questions/50940737/how-to-convert-a-graphic-to-a-sprite-in-pixijs
   * For example, rather than drawing a pin, we draw a square with a pin texture on it.
   * This is much more performant than drawing the graphics.
   */
  protected _cacheGraphics(): void {

    //
    // Viewfields
    //
    const viewfieldRect = new PIXI.Rectangle(-13, 0, 26, 52);
    const viewfieldOptions = { frame: viewfieldRect };  // texture the whole 26x26 region

    const viewfield = new PIXI.Graphics()       //   [-2,26]  ,---,  [2,26]
      .moveTo(-2, 26)                           //           /     \
      .lineTo(2, 26)                            //          /       \
      .lineTo(12, 4)                            //         /         \
      .bezierCurveTo(12, 0, -12, 0, -12, 4)     //        /           \
      .closePath()                              //       /             \
      .fill({ color: 0xffffff, alpha: 1 })      //       ""--_______--""         +y
      .stroke({ color: 0x444444, width: 1 });   // [-12,4]              [12,4]    |
                                                //            [0,0]               +-- +x

    const viewfieldDark = new PIXI.Graphics()
      .moveTo(-2, 26)
      .lineTo(2, 26)
      .lineTo(12, 4)
      .bezierCurveTo(12, 0, -12, 0, -12, 4)
      .closePath()                              // same viewfield, but outline light gray
      .fill({ color: 0x333333, alpha: 1 })      // and fill dark gray (not intended to be tinted)
      .stroke({ color: 0xcccccc, width: 1 });

    const viewfieldOutline = new PIXI.Graphics()
      .moveTo(-2, 26)
      .lineTo(2, 26)
      .lineTo(12, 4)
      .bezierCurveTo(12, 0, -12, 0, -12, 4)
      .closePath()
      .stroke({ color: 0xcccccc, width: 1 });

    this.createTexture('symbol', 'viewfield', viewfield, viewfieldOptions);
    this.createTexture('symbol', 'viewfieldDark', viewfieldDark, viewfieldOptions);
    this.createTexture('symbol', 'viewfieldOutline', viewfieldOutline, viewfieldOptions);


    const pano = new PIXI.Graphics()  // just a full circle - for panoramic / 360° images
      .circle(0, 0, 20)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 1 });

    const panoDark = new PIXI.Graphics()
      .circle(0, 0, 20)
      .fill({ color: 0x333333, alpha: 1 })
      .stroke({ color: 0xcccccc, width: 1 });

    const panoOutline = new PIXI.Graphics()
      .circle(0, 0, 20)
      .stroke({ color: 0xcccccc, width: 1 });

    this.createTexture('symbol', 'pano', pano);
    this.createTexture('symbol', 'panoDark', panoDark);
    this.createTexture('symbol', 'panoOutline', panoOutline);


    //
    // Markers
    //
    const pin = new PIXI.Graphics()             //              [0,-23]
      .moveTo(0, 0)                             //              _,-+-,_
      .bezierCurveTo(-2,-2, -8,-10, -8,-15)     //            /'       `\
      .bezierCurveTo(-8,-19, -4,-23, 0,-23)     //           :           :
      .bezierCurveTo(4,-23, 8,-19, 8,-15)       // [-8,-15]  :           :  [8,-15]
      .bezierCurveTo(8,-10, 2,-2, 0,0)          //            \         /
      .closePath()                              //             \       /
      .fill({ color: 0xffffff, alpha: 1 })      //              \     /
      .stroke({ color: 0x444444, width: 1 });   //               \   /      -y
                                                //                `+`        |
                                                //               [0,0]       +-- +x
    const boldPin = new PIXI.Graphics()
      .moveTo(0, 0)
      .bezierCurveTo(-2,-2, -8,-10, -8,-15)
      .bezierCurveTo(-8,-19, -4,-23, 0,-23)
      .bezierCurveTo(4,-23, 8,-19, 8,-15)
      .bezierCurveTo(8,-10, 2,-2, 0,0)
      .closePath()
      .fill({ color: 0xdddddd, alpha: 1 })
      .stroke({ color: 0x666666, width: 1.5 });    // same pin, bolder line stroke

    const xlargeSquare = new PIXI.Graphics()   // used as an "unknown" street sign
      .rect(-12, -12, 24, 24)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 2 });

    const largeSquare = new PIXI.Graphics()    // suitable to display an icon inside
      .rect(-8, -8, 16, 16)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 2 });

    const xlargeCircle = new PIXI.Graphics()   // used as an "unknown" detection
      .circle(0, 0, 12)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 2 });

    const largeCircle = new PIXI.Graphics()    // suitable to display an icon inside
      .circle(0, 0, 8)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 1 });

    const mediumCircle = new PIXI.Graphics()   // suitable for a streetview photo marker
      .circle(0, 0, 6)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 1 });

    const smallCircle = new PIXI.Graphics()    // suitable for a plain vertex
      .circle(0, 0, 4.5)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 1 });

    const taggedCircle = new PIXI.Graphics()   // a small circle with a dot inside
      .circle(0, 0, 4.5)
      .fill({ color: 0xffffff, alpha: 1 })
      .stroke({ color: 0x444444, width: 1 })
      .circle(0, 0, 2)
      .fill({ color: 0x000000, alpha: 1 });

    this.createTexture('symbol', 'pin', pin);
    this.createTexture('symbol', 'boldPin', boldPin);
    this.createTexture('symbol', 'xlargeSquare', xlargeSquare);
    this.createTexture('symbol', 'largeSquare', largeSquare);
    this.createTexture('symbol', 'xlargeCircle', xlargeCircle);
    this.createTexture('symbol', 'largeCircle', largeCircle);
    this.createTexture('symbol', 'mediumCircle', mediumCircle);
    this.createTexture('symbol', 'smallCircle', smallCircle);
    this.createTexture('symbol', 'taggedCircle', taggedCircle);


    // KeepRight
    const keepright = new PIXI.Graphics()
      .moveTo(15, 6.5)
      .lineTo(10.8, 6.5)
      .bezierCurveTo(12.2, 1.3, 11.7, 0.8, 11.2, 0.8)
      .lineTo(6.2, 0.8)
      .bezierCurveTo(5.8, 0.7, 5.4, 1, 5.4, 1.5)
      .lineTo(4.2, 10.2)
      .bezierCurveTo(4.1, 10.8, 4.6, 11.2, 5, 11.2)
      .lineTo(9.3, 11.2)
      .lineTo(7.6, 18.3)
      .bezierCurveTo(7.5, 18.8, 8, 19.3, 8.5, 19.3)
      .bezierCurveTo(8.8, 19.3, 9.1, 19.1, 9.2, 18.8)
      .lineTo(15.6, 7.8)
      .bezierCurveTo(16, 7.2, 15.6, 6.5, 15, 6.5)
      .closePath()
      .stroke({ color: 0x333333, width: 1 })
      .fill({ color: 0xffffff });

    // OSM note
    const osmnote = new PIXI.Graphics()
      .moveTo(17.5, 0)
      .lineTo(2.5,0)
      .bezierCurveTo(1.13, 0, 0, 1.12, 0, 2.5)
      .lineTo(0, 13.75)
      .bezierCurveTo(0, 15.12, 1.12, 16.25, 2.5, 16.25)
      .lineTo(6.25, 16.25)
      .lineTo(6.25, 19.53)
      .bezierCurveTo(6.25, 19.91, 6.68, 20.13, 7, 19.9)
      .lineTo(11.87, 16.25)
      .lineTo(17.49, 16.25)
      .bezierCurveTo(18.86, 16.25, 20, 15.12, 20, 13.75)
      .lineTo(20, 2.5)
      .bezierCurveTo(20, 1.13, 18.87, 0, 17.5, 0)
      .closePath()
      .stroke({ color: 0x333333, width: 1.5 })
      .fill({ color:0xffffff, alpha: 1 });

    const osmose = new PIXI.Graphics()
      .poly([16,3, 4,3, 1,6, 1,17, 4,20, 7,20, 10,27, 13,20, 16,20, 19,17.033, 19,6])
      .closePath()
      .fill({ color: 0xffffff })
      .stroke({ color: 0x333333, width: 1 });

    this.createTexture('symbol', 'keepright', keepright, { frame: new PIXI.Rectangle(0, 0, 20, 20) });
    this.createTexture('symbol', 'osmnote', osmnote);
    this.createTexture('symbol', 'osmose', osmose);


    //
    // Line markers
    //
    const midpoint = new PIXI.Graphics()        // [-3, 4]  ._                +y
      .poly([-3,4, 7,0, -3,-4])                 //          | "-._             |
      .fill({ color: 0xffffff, alpha: 1 })      //          |    _:>  [7,0]    +-- +x
      .stroke({ color: 0x444444, width: 1 });   //          |_,-"
                                                // [-3,-4]  '
    const oneway = new PIXI.Graphics()
      .poly([5,3, 0,3, 0,2, 5,2, 5,0, 10,2.5, 5,5])
      .fill({ color: 0xffffff, alpha: 1 });

    const twoway = new PIXI.Graphics()
      .poly([5,0, 5,2, 10,2, 10,0, 15,2.5,
             10,5, 10,3, 5,3, 5,5, 0,2.5])
      .fill({ color: 0xffffff, alpha: 1 });

    const sided = new PIXI.Graphics()
      .poly([0,5, 5,0, 0,-5])
      .fill({ color: 0xffffff, alpha: 1 });

    this.createTexture('symbol', 'midpoint', midpoint);
    this.createTexture('symbol', 'oneway', oneway);
    this.createTexture('symbol', 'twoway', twoway);
    this.createTexture('symbol', 'sided', sided);


    //
    // Low-res areas
    // We can replace areas with these sprites when they are very small
    // They are all sized to 10x10 (would look fine scaled down but not up)
    //
    const lowresSquare = new PIXI.Graphics()
      .rect(-5, -5, 10, 10)
      .fill({ color: 0xffffff, alpha: 0.6 })
      .stroke({ color: 0xffffff, width: 1 });

    const lowresEll = new PIXI.Graphics()
      .poly([-5,-5, 5,-5, 5,5, 1,5, 1,1, -5,1, -5,-5])
      .fill({ color: 0xffffff, alpha: 0.6 })
      .stroke({ color: 0xffffff, width: 1 });

    const lowresCircle = new PIXI.Graphics()
      .circle(0, 0, 5)
      .fill({ color: 0xffffff, alpha: 0.6 })
      .stroke({ color: 0xffffff, width: 1 });

    this.createTexture('symbol', 'lowres-square', lowresSquare);
    this.createTexture('symbol', 'lowres-ell', lowresEll);
    this.createTexture('symbol', 'lowres-circle', lowresCircle);

    //
    // Low-res unfilled areas
    // For wireframe mode rendering (no fills at all)
    //
    const lowresUnfilledSquare = new PIXI.Graphics()
      .rect(-5, -5, 10, 10)
      .stroke({ color: 0xffffff, width: 1 });

    const lowresUnfilledEll = new PIXI.Graphics()
      .poly([-5,-5, 5,-5, 5,5, 1,5, 1,1, -5,1, -5,-5])
      .stroke({ color: 0xffffff, width: 1 });

    const lowresUnfilledCircle = new PIXI.Graphics()
      .circle(0, 0, 5)
      .stroke({ color: 0xffffff, width: 1 });

    this.createTexture('symbol', 'lowres-unfilled-square', lowresUnfilledSquare);
    this.createTexture('symbol', 'lowres-unfilled-ell', lowresUnfilledEll);
    this.createTexture('symbol', 'lowres-unfilled-circle', lowresUnfilledCircle);
  }

}
